import sys
sys.path.append('..')
from base.spider import Spider

def parse_raw(text):
    groups = []
    current = None
    for line in text.splitlines():
        line = line.strip()
        if not line or line.startswith('#'):
            continue
        if '#genre#' in line:
            gname = line.split(',')[0].strip()
            if gname:
                current = {'name': gname, 'channels': []}
                groups.append(current)
            continue
        if ',' in line:
            name, url = line.split(',', 1)
            name, url = name.strip(), url.strip()
            if name and url:
                if current is None:
                    current = {'name': '直播', 'channels': []}
                    groups.append(current)
                current['channels'].append({'name': name, 'url': url})
    return groups

CHANNELS = parse_raw(RAW)
CLASSES = [{'type_name': g['name'], 'type_id': str(i)} for i, g in enumerate(CHANNELS)]

class Spider(Spider):
    def getName(self):
        return "xxx资源"

    def init(self, extend=""):
        pass

    def isVideoFormat(self, url):
        pass

    def manualVideoCheck(self):
        pass

    def homeContent(self, filter):
        return {'class': CLASSES}

    def categoryContent(self, tid, pg, filter, extend):
        tid = int(tid)
        group = CHANNELS[tid]['channels']
        videos = []
        for idx, ch in enumerate(group):
            videos.append({
                'vod_id': f"{tid}_{idx}",
                'vod_name': ch['name'],
                'vod_pic': '',
                'vod_remarks': CHANNELS[tid]['name'],
                'vod_play_url': ch['url']
            })
        return {'list': videos, 'page': pg, 'pagecount': 1, 'limit': len(videos), 'total': len(videos)}

    def detailContent(self, ids):
        vid = ids[0]
        tid, idx = vid.split('_')
        tid = int(tid)
        idx = int(idx)
        ch = CHANNELS[tid]['channels'][idx]
        vod = {
            'vod_id': vid,
            'vod_name': ch['name'],
            'vod_pic': '',
            'vod_remarks': CHANNELS[tid]['name'],
            'vod_content': ch['name'],
            'vod_play_from': '视频线路',
            'vod_play_url': ch['url']
        }
        return {'list': [vod]}

    def playerContent(self, flag, id, vipFlags):
        return {'parse': 0, 'playUrl': '', 'url': id, 'header': ''}